import React, { useEffect, useState } from "react";
import "./BadgesPage.css";
import { useNavigate } from "react-router-dom";

const badgeIconMap = {
  bronze_volunteer: "https://up.yimg.com/ib/th/id/OIP.OHs_yaTRMl1wF9glVaPZmgHaHa?pid=Api&rs=1&c=1&qlt=95&w=105&h=105",
  silver_volunteer: "https://up.yimg.com/ib/th/id/OIP.8jVsS3Paqnphh1RUaZRO_gHaHa?pid=Api&rs=1&c=1&qlt=95&w=120&h=120",
  gold_volunteer: "https://up.yimg.com/ib/th/id/OIP.M2jWfXFIT6yiFKdza-Xy9QHaHa?pid=Api&rs=1&c=1&qlt=95&w=121&h=121",
  silver_donor: "https://up.yimg.com/ib/th/id/OIP.8jVsS3Paqnphh1RUaZRO_gHaHa?pid=Api&rs=1&c=1&qlt=95&w=120&h=120",
  gold_donor: "https://up.yimg.com/ib/th/id/OIP.M2jWfXFIT6yiFKdza-Xy9QHaHa?pid=Api&rs=1&c=1&qlt=95&w=121&h=121",
  platinum_donor: "https://tse3.mm.bing.net/th/id/OIP.Imd7GlakFy5b_od5xomrDAHaHa?pid=Api&P=0&h=180",
};

const badgeActionMap = {
  bronze_volunteer: "Volunteer Now",
  silver_volunteer: "Volunteer Now",
  gold_volunteer: "Volunteer Now",
  silver_donor: "Donate Now",
  gold_donor: "Donate Now",
  platinum_donor: "Donate Now",
};

export default function BadgesPage({ token }) {
  const [badges, setBadges] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    async function fetchBadges() {
      try {
        const res = await fetch("http://localhost:4000/achievements", {
          headers: { Authorization: token },
        });
        const data = await res.json();
        const mapped = (data.badges || []).map((b) => ({
          ...b,
          icon: badgeIconMap[b.key] || "",
          action: badgeActionMap[b.key] || "Participate",
        }));
        setBadges(mapped);
      } catch (err) {
        console.error("Error fetching badges:", err);
      }
    }
    fetchBadges();
  }, [token]);

  return (
    <div className="badges-wrapper">
      <h1 className="badges-title">Badges</h1>

      {badges.length === 0 ? (
        <p className="no-badges-msg">No badges yet — participate to earn rewards.</p>
      ) : (
        <div className="badges-grid">
          {badges.map((b, i) => (
            <div className="badge-card" key={i}>
              <img src={b.icon} alt={b.title} className="badge-icon" />
              <h2>{b.title}</h2>
              <p>{b.desc}</p>
              <button
                className="badge-action-btn"
                onClick={() =>
                  navigate(b.action === "Donate Now" ? "/donate" : "/volunteer")
                }
              >
                {b.action}
              </button>
            </div>
          ))}
        </div>
      )}

      <div className="back-btn">
        <button onClick={() => (window.location.href = "/")}>← Back to Home</button>
      </div>
    </div>
  );
}
